-- 返工（队长独立验收第 2 项）：剧情搜索经旧视频标签链（Vod::listCacheData，plot=1）的随机排序有两种算法，阈值为计数 2000
-- （Vod.php:500-537）。在主用例之后导入：2001 行有分集剧情的已审核视频（vod_id 1000..3000，首字母 P 2000 行、Q 1 行），
-- 使 letter=P 的计数恰为 2000（算法一，随机页 1..101）、letter=P,Q 为 2001（算法二，全表 MIN/MAX 取候选下标）。
-- 名称不含主用例的检索词；全部是合成数据。
INSERT INTO mac_vod (vod_pic_screenshot,vod_id,type_id,vod_name,vod_en,vod_sub,vod_status,vod_letter,vod_level,vod_plot,vod_time,vod_time_add,vod_hits_week,vod_pwd,vod_copyright,vod_content,vod_play_from,vod_play_url,vod_down_from,vod_down_url,vod_plot_name,vod_plot_detail) SELECT '', 1000 + n, 1, CONCAT('批量剧', n), CONCAT('piliangju', n), '', 1, IF(n = 2000, 'Q', 'P'), 1, 1, 1600000000 + n, 1590000000 + n, 5000 + (n * 7) % 2001, '', 0, '', '', '', '', '', '第1集', '剧情' FROM (SELECT a.d + b.d * 10 + c.d * 100 + e.d * 1000 AS n FROM (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a, (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b, (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) c, (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2) e) t WHERE n <= 2000;
